cat > test/agent-replay.test.cjs <<'EOF'
const test=require('node:test'),assert=require('node:assert/strict');
const {Orders}=require('../service.cjs');
const ev=(event,op,...args)=>({event,op,args});
test('replay applies, skips duplicates, survives restart',()=>{
 const o=new Orders({x:10},{x:'7'});
 assert.equal(o.replay([ev('1','reserve','a','x',4,0,10),ev('2','fulfill','a',2,1),ev('3','expire',5)]),3);
 assert.equal(o.replay([ev('1','reserve','a','x',4,0,10),ev('2','fulfill','a',2,1)]),0);
 const p=Orders.loads(o.dumps());
 assert.equal(p.replay([ev('2','fulfill','a',2,1),ev('4','refund','a',1)]),1);
 assert.equal(p.replay([ev('4','refund','a',1)]),0);
 assert.equal(p.available('x',10),9);
 assert.equal(o.available('x'),6);
});
test('failures roll back everything',()=>{
 const o=new Orders({x:5});o.replay([ev('1','reserve','a','x',1)]);
 const before=o.dumps();
 const cases=[
  [ev('2','reserve','b','x',2),ev('1','reserve','a','x',2)],
  [ev('2','reserve','b','x',2),ev('3','bogus')],
  [ev('2','reserve','b','x',2),ev('3','reserve','c','x',0)],
  [ev('2','reserve','b','x',2),ev('3','reserve','c','x',9)],
  [ev('2','reserve','b','x',2),ev('3','fulfill','zz',1)],
  [ev('2','reserve','b','x',2),ev('2','reserve','b','x',3)],
  [ev('2','reserve','b','x',2),{event:'9',op:'refund',args:'no'}],
 ];
 for(const c of cases){assert.throws(()=>o.replay(c),RangeError);assert.equal(o.dumps(),before);}
 assert.throws(()=>o.replay('x'),RangeError);
});
EOF
